import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build an exact minimum-cost shared directed broadcast tree for small receiver sets.

    The algorithm uses directed-Steiner subset dynamic programming to minimize
    the union cost of links shared by receiver paths.  It reconstructs one
    source-to-destination route per receiver and partition.  For more than
    twelve distinct receivers, it uses independent lowest-cost routes to keep
    the search bounded.
    """
    import heapq

    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from(
        [(u, v) for u, v, data in h.edges(data=True)
         if data.get("cost") is None]
    )

    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))
    direct_paths = {
        dst: nx.dijkstra_path(h, src, dst, weight="cost")
        for dst in terminals
    }
    selected_paths = direct_paths

    if terminals and len(terminals) <= 12:
        nodes = list(h.nodes())
        inf = float("inf")
        state_count = 1 << len(terminals)
        dp = [{node: inf for node in nodes} for _ in range(state_count)]
        action = [{} for _ in range(state_count)]

        for mask in range(1, state_count):
            submask = (mask - 1) & mask
            while submask:
                other = mask ^ submask
                if other and submask < other:
                    for node in nodes:
                        candidate = dp[submask][node] + dp[other][node]
                        if candidate < dp[mask][node]:
                            dp[mask][node] = candidate
                            action[mask][node] = ("join", submask, other)
                submask = (submask - 1) & mask

            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                dp[mask][terminal] = 0.0
                action[mask][terminal] = ("terminal",)

            queue = [
                (dp[mask][node], node)
                for node in nodes if dp[mask][node] < inf
            ]
            heapq.heapify(queue)

            while queue:
                value, node = heapq.heappop(queue)
                if value != dp[mask][node]:
                    continue
                for parent in h.predecessors(node):
                    candidate = value + float(h[parent][node]["cost"])
                    if candidate < dp[mask][parent]:
                        dp[mask][parent] = candidate
                        action[mask][parent] = ("edge", node)
                        heapq.heappush(queue, (candidate, parent))

        used_edges = set()

        def collect(mask, node):
            choice = action[mask].get(node)
            if choice is None or choice[0] == "terminal":
                return
            if choice[0] == "edge":
                child = choice[1]
                used_edges.add((node, child))
                collect(mask, child)
            else:
                collect(choice[1], node)
                collect(choice[2], node)

        collect(state_count - 1, src)
        tree = nx.DiGraph()
        tree.add_edges_from(used_edges)

        try:
            selected_paths = {
                dst: nx.shortest_path(
                    tree, src, dst,
                    weight=lambda u, v, data: float(h[u][v]["cost"])
                )
                for dst in terminals
            }
        except nx.NetworkXNoPath:
            selected_paths = direct_paths

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    for dst in dsts:
        if dst == src:
            continue
        for u, v in zip(selected_paths[dst], selected_paths[dst][1:]):
            for partition in range(num_partitions):
                bc_topology.append_dst_partition_path(
                    dst, partition, [u, v, G[u][v]]
                )
    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
